"import fs from 'fs';

async function crawl() {
  const url = 'https://babimate.com/products/babiguard-1?variant=47762970378518';
  const res = await fetch(url, {
    headers: {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
    }
  });
  const html = await res.text();
  console.log('HTML size:', html.length);
  fs.writeFileSync('scratch/babimate_pdp.html', html, 'utf8');

  // Also fetch the product JSON
  const jsonRes = await fetch('https://babimate.com/products/babiguard-1.json', {
    headers: {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
    }
  });
  const productData = await jsonRes.json();
  fs.writeFileSync('scratch/babimate_product.json', JSON.stringify(productData, null, 2), 'utf8');
  console.log('Product Title:', productData.product?.title);
  console.log('Vendor:', productData.product?.vendor);
  console.log('Product Type:', productData.product?.product_type);
  console.log('Tags:', productData.product?.tags);
  console.log('Variants:', productData.product?.variants?.length);
  console.log('Images:', productData.product?.images?.length);
  console.log('Saved to scratch/babimate_pdp.html and scratch/babimate_product.json');
}

crawl().catch(console.error);
"

