const priceMatches = html.match(/(\$|₫|€|£|¥)\s*[\d,\.]+/g);
console.log('Sample price strings:', priceMatches?.slice(0, 10));

// Let's check dsdujr-vn currency via API
const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = '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';
const SHOP_DOMAIN = 'dsdujr-vn.myshopify.com';

async function checkShop() {
  const tokenRes = await fetch('https://' + SHOP_DOMAIN + '/admin/oauth/access_token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, grant_type: 'client_credentials' })
  });
  const { access_token } = await tokenRes.json();
  const shopRes = await fetch('https://' + SHOP_DOMAIN + '/admin/api/2024-01/shop.json', {
    headers: { 'X-Shopify-Access-Token': access_token }
