  const templateContent = fs.readFileSync('templates/product.babiguard.json', 'utf8');
  await uploadAsset(token, 'templates/product.babiguard.json', templateContent);

  console.log('\nAll assets uploaded to live theme!');
}

main().catch(console.error);
