"import fs from 'fs';

const SHOP_DOMAIN = 'dsdujr-vn.myshopify.com';
const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = process.env.SHOPIFY_API_SECRET || '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';

async function getAccessToken() {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      client_id: CLIENT_ID,
      client_secret: CLIENT_SECRET,
      grant_type: 'client_credentials'
    })
  });
  const data = await res.json();
  return data.access_token;
}

async function inspect() {
  const token = await getAccessToken();
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/products/15424286589113.json`, {
    headers: { 'X-Shopify-Access-Token': token }
  });
  const data = await res.json();
  if (!data.product) {
    console.error('Product not found:', data);
    return;
  }
  fs.writeFileSync('scratch/rehab_glove_product.json', JSON.stringify(data.product, null, 2));
  console.log('Title:', data.product.title);
  console.log('Handle:', data.product.handle);
  console.log('Status:', data.product.status);
  console.log('Template Suffix:', data.product.template_suffix);
  console.log('Options:', JSON.stringify(data.product.options, null, 2));
  console.log('Variants Count:', data.product.variants.length);
  console.log('Images Count:', data.product.images.length);
  console.log('Variants:');
  console.log(JSON.stringify(data.product.variants.map(v => ({
    id: v.id,
    title: v.title,
    price: v.price,
    compare_at_price: v.compare_at_price,
    option1: v.option1,
    option2: v.option2,
    option3: v.option3,
    sku: v.sku,
    available: v.inventory_quantity
  })), null, 2));
}

inspect().catch(console.error);
