"import fs from 'fs';

const html = fs.readFileSync('scratch/houdini_full_page.html', 'utf8');
const idx = html.indexOf('Breakthrough Design & Unmatched Performance');
const endIdx = html.indexOf('</section>', idx);
const sectionHtml = html.slice(idx - 200, endIdx + 100);

const items = [];
const slideRegex = /<li class="splide__slide">([\s\S]*?)<\/li>/gi;
let slideMatch;

while ((slideMatch = slideRegex.exec(sectionHtml)) !== null) {
  const block = slideMatch[1];
  const imgMatch = block.match(/src="([^"]+)"/);
  const titleMatch = block.match(/<h3>([^<]+)<\/h3>/);
  const descMatch = block.match(/<p>([^<]+)<\/p>/);

  if (titleMatch && descMatch) {
    let src = imgMatch ? imgMatch[1] : '';
    if (src.startsWith('//')) src = 'https:' + src;
    items.push({
      image: src,
      title: titleMatch[1].trim(),
      desc: descMatch[1].trim()
    });
  }
}

console.log('Extracted items count:', items.length);
console.log(JSON.stringify(items, null, 2));
fs.writeFileSync('scratch/breakthrough_items.json', JSON.stringify(items, null, 2));
"

