        font-size: 11px;
      }
      #Section-{{ section.id }} .lr-select-pill-arrow {
        right: 6px;
        width: 7px;
      }
      #Section-{{ section.id }} .lr-selector-label {
        font-size: 11px;
        margin-bottom: 3px;
      }`
);

